import java.lang.reflect.Method;

public class HashProbe {
    public static void main(String[] a) throws Exception {
        Method m = Class.forName("Main").getDeclaredMethod("getHash", String.class);
        m.setAccessible(true);
        StringBuilder sb = new StringBuilder();
        String[] fixed = {"", "a", "A", "0", "192.168.1.1", "192.168.1.1##VN0", "192.168.1.1##VN9",
                          "服务器中文", "服务器中文##VN5",
                          " ", "￿", "😀", "client-abc", "##", "10.0.0.7##VN3",
                          "ÿĀ߿"};
        for (String s : fixed) {
            sb.append("F[").append(s).append("]=").append(m.invoke(null, s)).append('\n');
        }
        java.util.Random r = new java.util.Random(42);
        long acc = 0;
        int negatives = 0;
        for (int i = 0; i < 200000; i++) {
            int len = r.nextInt(24);
            StringBuilder k = new StringBuilder();
            for (int j = 0; j < len; j++) k.append((char) r.nextInt(0x10000));
            int h = (Integer) m.invoke(null, k.toString());
            if (h < 0) negatives++;
            acc = acc * 31 + h;
            if (i < 40) sb.append("S").append(i).append('=').append(h).append('\n');
        }
        sb.append("SWEEP_ACC=").append(acc).append('\n');
        sb.append("NEGATIVES=").append(negatives).append('\n');
        System.out.print(sb);
    }
}

