public class FindKey {
    public static void main(String[] a) throws Exception {
        Method m = Class.forName("Main").getDeclaredMethod("getHash", String.class);
        m.setAccessible(true);
        String server = "192.168.1.1";
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < 10; i++) {
            int h = (Integer) m.invoke(null, server + "##VN" + i);
            System.out.println("VN" + i + " = " + h);
            if (h > max) max = h;
        }
        System.out.println("MAXVN=" + max);
        for (int i = 0; i < 5000000; i++) {
            String k = "c" + i;
            int h = (Integer) m.invoke(null, k);
            if (h > max) {
                System.out.println("ABOVE_ALL key=" + k + " hash=" + h);
                break;
            }
        }
    }
}

import java.lang.reflect.Method;

public class IpProbe {
    public static void main(String[] a) throws Exception {
        Method m = Class.forName("Main").getDeclaredMethod("generateIp");
        m.setAccessible(true);
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        int dotCountBad = 0;
        for (int i = 0; i < 200000; i++) {
            String ip = (String) m.invoke(null);
            String[] parts = ip.split("\\.");
            if (parts.length != 4) { dotCountBad++; continue; }
            for (String p : parts) {
                int v = Integer.parseInt(p);
                if (v < min) min = v;
                if (v > max) max = v;
            }
        }
        System.out.println("octet_min=" + min + " octet_max=" + max + " badFormat=" + dotCountBad);
    }
}
